#include <string.h>

#include "sha256.h"

static const uint32_t IV[8] = {
    0x6A09E667, 0xBB67AE85, 0x3C6EF372, 0xA54FF53A, 0x510E527F, 0x9B05688C, 0x1F83D9AB, 0x5BE0CD19};

void sha256_init_state(uint32_t h[8]) {
    memcpy(h, IV, sizeof(IV));
}

#if defined(__thumb2__)

// Thumb-2, generated by scripts/gen_asm.py (sha256_thumb2.S): a message-schedule
// loop and a round loop (8 rounds an iteration), small enough for the core's ~2 KB
// instruction cache, reading K (and a 0 sentinel) from a RAM copy of sha256_k.
void                  sha256_compress_asm(uint32_t h[8], const uint32_t block[16], const uint32_t *k);
void                  sha256_oneblock16_asm(uint32_t out[4], const uint32_t block[16], const uint32_t *k);
extern const uint32_t sha256_k[65];

static uint32_t g_k[65];

void sha256_setup(void) {
    memcpy(g_k, sha256_k, sizeof(g_k));
}

void sha256_compress(uint32_t h[8], const uint32_t block[16]) {
    sha256_compress_asm(h, block, g_k);
}

void sha256_oneblock16(uint32_t out[4], const uint32_t block[16]) {
    sha256_oneblock16_asm(out, block, g_k);
}

#else

// Portable C (host builds, tests/native).

static const uint32_t K[64] = {
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
};

#define ROTR(x, n) (((x) >> (n)) | ((x) << (32 - (n))))

void sha256_setup(void) {}

void sha256_compress(uint32_t h[8], const uint32_t block[16]) {
    const uint8_t *p = (const uint8_t *) block;
    uint32_t       w[64], s[8];
    for (unsigned i = 0; i < 16; i++) {
        w[i] = (uint32_t) p[4 * i] << 24 | (uint32_t) p[4 * i + 1] << 16 | (uint32_t) p[4 * i + 2] << 8 | p[4 * i + 3];
    }
    for (unsigned i = 16; i < 64; i++) {
        uint32_t s0 = ROTR(w[i - 15], 7) ^ ROTR(w[i - 15], 18) ^ (w[i - 15] >> 3);
        uint32_t s1 = ROTR(w[i - 2], 17) ^ ROTR(w[i - 2], 19) ^ (w[i - 2] >> 10);
        w[i] = w[i - 16] + s0 + w[i - 7] + s1;
    }
    memcpy(s, h, sizeof(s));
    for (unsigned i = 0; i < 64; i++) {
        uint32_t t1 = s[7] + (ROTR(s[4], 6) ^ ROTR(s[4], 11) ^ ROTR(s[4], 25)) + (s[6] ^ (s[4] & (s[5] ^ s[6]))) + K[i] + w[i];
        uint32_t t2 = (ROTR(s[0], 2) ^ ROTR(s[0], 13) ^ ROTR(s[0], 22)) + ((s[0] & s[1]) | (s[2] & (s[0] | s[1])));
        memmove(s + 1, s, 7 * sizeof(uint32_t));
        s[4] += t1;
        s[0] = t1 + t2;
    }
    for (unsigned i = 0; i < 8; i++) {
        h[i] += s[i];
    }
}

void sha256_oneblock16(uint32_t out[4], const uint32_t block[16]) {
    uint32_t h[8];
    uint8_t *o = (uint8_t *) out;
    sha256_init_state(h);
    sha256_compress(h, block);
    for (unsigned i = 0; i < 4; i++) {
        o[4 * i] = (uint8_t) (h[i] >> 24);
        o[4 * i + 1] = (uint8_t) (h[i] >> 16);
        o[4 * i + 2] = (uint8_t) (h[i] >> 8);
        o[4 * i + 3] = (uint8_t) h[i];
    }
}

#endif
